-- MIT. The normative session tool bundle (draft 2020-12): shared $defs and the ten default tool declarations.
return [==[
{
 "$schema":"https://json-schema.org/draft/2020-12/schema","$id":"urn:bee:session",
 "$defs":{
  "Ref":{"type":"string","minLength":1,"maxLength":256},
  "SessionRef":{"allOf":[{"$ref":"#/$defs/Ref"},{"pattern":"^bs:[^:]+:[^:]+:[^:]+$"}]},
  "WorkRef":{"allOf":[{"$ref":"#/$defs/Ref"},{"pattern":"^bw:[^:]+:[^:]+:[^:]+$"}]},
  "OpRef":{"allOf":[{"$ref":"#/$defs/Ref"},{"pattern":"^bo:[^:]+:[^:]+:[^:]+$"}]},
  "JoinRef":{"allOf":[{"$ref":"#/$defs/Ref"},{"pattern":"^bj:[^:]+:[^:]+:[^:]+$"}]},
  "Subject":{"oneOf":[{"$ref":"#/$defs/WorkRef"},{"$ref":"#/$defs/OpRef"}]},
  "Text":{"type":"string","maxLength":16384},
  "Key":{"type":"string","minLength":1,"maxLength":128},
  "Cursor":{"type":"string","minLength":1,"maxLength":2048},
  "Time":{"type":"string","format":"date-time"},
  "Pos":{"type":"integer","minimum":1},
  "Nat":{"type":"integer","minimum":0},
  "Timeout":{"type":"integer","minimum":0,"maximum":60000,"default":30000},
  "JSON":{},
  "Refs":{"type":"array","maxItems":64,"items":{"$ref":"#/$defs/Ref"}},
  "Works":{"type":"array","minItems":1,"maxItems":64,"uniqueItems":true,"items":{"$ref":"#/$defs/WorkRef"}},
  "Input":{"oneOf":[{"$ref":"#/$defs/Text"},{"type":"object","additionalProperties":false,"required":["schema","value"],"properties":{"schema":{"$ref":"#/$defs/Ref"},"value":{"$ref":"#/$defs/JSON"}}}]},
  "Profile":{"type":"object","additionalProperties":false,"required":["id","revision"],"properties":{"id":{"$ref":"#/$defs/Ref"},"revision":{"$ref":"#/$defs/Pos"}}},
  "Limits":{"type":"object","additionalProperties":false,"properties":{"active_ms":{"$ref":"#/$defs/Pos"},"model_steps":{"$ref":"#/$defs/Pos"},"tool_calls":{"$ref":"#/$defs/Pos"},"recovery_attempts":{"$ref":"#/$defs/Nat"},"queue_ms":{"$ref":"#/$defs/Pos"}}},
  "ManagedSpec":{"type":"object","additionalProperties":false,"required":["definition"],"properties":{"definition":{"$ref":"#/$defs/Ref"},"profile":{"$ref":"#/$defs/Profile"},"title":{"type":"string","maxLength":512},"workdir":{"$ref":"#/$defs/Ref"}}},
  "Sender":{"type":"object","additionalProperties":false,"required":["kind","id"],"properties":{"kind":{"enum":["session","principal"]},"id":{"$ref":"#/$defs/Ref"}}},
  "Evidence":{"type":"object","additionalProperties":false,"required":["summary","artifacts"],"properties":{"summary":{"$ref":"#/$defs/Text"},"artifacts":{"$ref":"#/$defs/Refs"}}},
  "Fault":{"type":"object","additionalProperties":false,"required":["code","message","retry"],"properties":{"code":{"type":"string","minLength":1,"maxLength":128},"message":{"$ref":"#/$defs/Text"},"retry":{"enum":["never","same_key","refresh","reconcile"]},"operation_key":{"$ref":"#/$defs/Key"},"operation":{"$ref":"#/$defs/OpRef"},"current_revision":{"$ref":"#/$defs/Pos"},"evidence":{"$ref":"#/$defs/Evidence"},"retry_after_ms":{"$ref":"#/$defs/Nat"}}},
  "Reply":{"oneOf":[{"type":"object","additionalProperties":false,"required":["ok","value"],"properties":{"ok":{"const":true},"value":{}}},{"type":"object","additionalProperties":false,"required":["ok","error"],"properties":{"ok":{"const":false},"error":{"$ref":"#/$defs/Fault"}}}]},
  "MutationReply":{"allOf":[{"$ref":"#/$defs/Reply"},{"properties":{"error":{"required":["operation_key"]}}}]},
  "Result":{"oneOf":[{"type":"object","additionalProperties":false,"required":["outcome","schema","value","artifacts","usage"],"properties":{"outcome":{"const":"succeeded"},"schema":{"$ref":"#/$defs/Ref"},"value":{"$ref":"#/$defs/JSON"},"artifacts":{"$ref":"#/$defs/Refs"},"usage":{"$ref":"#/$defs/Refs"}}},{"type":"object","additionalProperties":false,"required":["outcome","error","artifacts"],"properties":{"outcome":{"enum":["failed","cancelled","rejected"]},"error":{"$ref":"#/$defs/Fault"},"artifacts":{"$ref":"#/$defs/Refs"}}}]},
  "Action":{"type":"object","additionalProperties":false,"required":["operation","label"],"properties":{"operation":{"$ref":"#/$defs/Ref"},"label":{"$ref":"#/$defs/Text"}}},
  "Actions":{"type":"array","maxItems":64,"items":{"$ref":"#/$defs/Action"}},
  "Blocker":{"type":"object","additionalProperties":false,"required":["kind","message","subject","actions"],"properties":{"kind":{"enum":["budget","authority","capacity","recovery"]},"message":{"$ref":"#/$defs/Text"},"subject":{"$ref":"#/$defs/Ref"},"actions":{"$ref":"#/$defs/Actions"}}},
  "WorkReceipt":{"type":"object","additionalProperties":false,"required":["work","session","operation","committed_at","sequence","kind","state","output_schema","sender"],"properties":{"work":{"$ref":"#/$defs/WorkRef"},"session":{"$ref":"#/$defs/SessionRef"},"operation":{"$ref":"#/$defs/OpRef"},"committed_at":{"$ref":"#/$defs/Time"},"sequence":{"$ref":"#/$defs/Pos"},"kind":{"const":"request"},"state":{"const":"queued"},"output_schema":{"$ref":"#/$defs/Ref"},"sender":{"$ref":"#/$defs/Sender"}}},
  "WorkState":{"type":"object","additionalProperties":false,"required":["work","session","sender","revision","phase","cancelling"],"properties":{"work":{"$ref":"#/$defs/WorkRef"},"session":{"$ref":"#/$defs/SessionRef"},"sender":{"$ref":"#/$defs/Sender"},"revision":{"$ref":"#/$defs/Pos"},"phase":{"enum":["queued","reserved","accepted","settled"]},"cancelling":{"type":"boolean"},"blocker":{"$ref":"#/$defs/Blocker"},"uncertainty":{"$ref":"#/$defs/Evidence"},"result":{"$ref":"#/$defs/Result"}},"oneOf":[{"properties":{"phase":{"const":"settled"},"cancelling":{"const":false}},"required":["result"],"not":{"anyOf":[{"required":["blocker"]},{"required":["uncertainty"]}]}},{"properties":{"phase":{"enum":["queued","reserved","accepted"]}},"not":{"required":["result"]}}]},
  "ControlReceipt":{"type":"object","additionalProperties":false,"required":["operation","subject","state","effect"],"properties":{"operation":{"$ref":"#/$defs/OpRef"},"subject":{"oneOf":[{"$ref":"#/$defs/WorkRef"},{"$ref":"#/$defs/SessionRef"}]},"state":{"const":"requested"},"effect":{"enum":["cancel","close"]}}},
  "ControlResult":{"oneOf":[{"type":"object","additionalProperties":false,"required":["effect","state","work","evidence"],"properties":{"effect":{"const":"cancel"},"state":{"enum":["stopped","already_terminal"]},"work":{"$ref":"#/$defs/WorkRef"},"evidence":{"$ref":"#/$defs/Evidence"}}},{"type":"object","additionalProperties":false,"required":["effect","state","session","cleanup"],"properties":{"effect":{"const":"close"},"state":{"const":"closed"},"session":{"$ref":"#/$defs/SessionRef"},"cleanup":{"enum":["complete","pending","uncertain"]}}}]},
  "OperationReceipt":{"oneOf":[{"$ref":"#/$defs/OpenReceipt"},{"$ref":"#/$defs/WorkReceipt"},{"$ref":"#/$defs/ControlReceipt"}]},
  "OperationResult":{"oneOf":[{"type":"object","additionalProperties":false,"required":["kind","value"],"properties":{"kind":{"const":"receipt"},"value":{"$ref":"#/$defs/OperationReceipt"}}},{"type":"object","additionalProperties":false,"required":["kind","value"],"properties":{"kind":{"const":"control"},"value":{"$ref":"#/$defs/ControlResult"}}},{"type":"object","additionalProperties":false,"required":["kind","result"],"properties":{"kind":{"const":"result"},"result":{"$ref":"#/$defs/Result"}}}]},
  "Await":{"type":"object","additionalProperties":false,"required":["subject_kind","subject","cursor","tag"],"properties":{"subject_kind":{"enum":["work","operation"]},"subject":{"$ref":"#/$defs/Subject"},"cursor":{"$ref":"#/$defs/Cursor"},"tag":{"enum":["ready","pending","blocked","uncertain"]},"result":{},"reason":{"const":"timeout"},"blocker":{"$ref":"#/$defs/Blocker"},"evidence":{"$ref":"#/$defs/Evidence"}},"allOf":[{"oneOf":[{"properties":{"subject_kind":{"const":"work"},"subject":{"$ref":"#/$defs/WorkRef"},"result":{"$ref":"#/$defs/Result"}}},{"properties":{"subject_kind":{"const":"operation"},"subject":{"$ref":"#/$defs/OpRef"},"result":{"$ref":"#/$defs/OperationResult"}}}]},{"$ref":"#/$defs/AwaitBranches"}]},
  "AwaitBranches":{"oneOf":[{"properties":{"tag":{"const":"ready"}},"required":["result"],"not":{"anyOf":[{"required":["reason"]},{"required":["blocker"]},{"required":["evidence"]}]}},{"properties":{"tag":{"const":"pending"}},"required":["reason"],"not":{"anyOf":[{"required":["result"]},{"required":["blocker"]},{"required":["evidence"]}]}},{"properties":{"tag":{"const":"blocked"}},"required":["blocker"],"not":{"anyOf":[{"required":["result"]},{"required":["reason"]},{"required":["evidence"]}]}},{"properties":{"tag":{"const":"uncertain"}},"required":["evidence"],"not":{"anyOf":[{"required":["result"]},{"required":["reason"]},{"required":["blocker"]}]}}]},
  "JoinResult":{"type":"object","additionalProperties":false,"required":["succeeded","winners"],"properties":{"succeeded":{"type":"boolean"},"winners":{"type":"array","maxItems":64,"uniqueItems":true,"items":{"$ref":"#/$defs/WorkRef"}},"values":{"type":"array","maxItems":64,"items":{"$ref":"#/$defs/JSON"}}},"if":{"properties":{"succeeded":{"const":true}}},"then":{"required":["values"],"properties":{"winners":{"minItems":1}}},"else":{"not":{"required":["values"]}}},
  "JoinAwait":{"type":"object","additionalProperties":false,"required":["subject_kind","subject","cursor","tag","children"],"properties":{"subject_kind":{"const":"join"},"subject":{"$ref":"#/$defs/JoinRef"},"cursor":{"$ref":"#/$defs/Cursor"},"tag":{"enum":["ready","pending","blocked","uncertain"]},"children":{"type":"array","minItems":1,"maxItems":64,"items":{"allOf":[{"$ref":"#/$defs/Await"},{"properties":{"subject_kind":{"const":"work"}}}]}},"result":{"$ref":"#/$defs/JoinResult"},"reason":{"const":"timeout"},"blocker":{"$ref":"#/$defs/Blocker"},"evidence":{"$ref":"#/$defs/Evidence"}},"allOf":[{"$ref":"#/$defs/AwaitBranches"}]},
  "Continuity":{"type":"object","additionalProperties":false,"required":["mode"],"properties":{"mode":{"enum":["exact","provider_resume","reconstructed","fresh"]},"evidence":{"$ref":"#/$defs/Evidence"}}},
  "LastResult":{"type":"object","additionalProperties":false,"required":["work","outcome","summary","at"],"properties":{"work":{"$ref":"#/$defs/WorkRef"},"outcome":{"enum":["succeeded","failed","cancelled","rejected"]},"summary":{"type":"string","maxLength":4096},"at":{"$ref":"#/$defs/Time"}}},
  "SessionSnapshot":{"type":"object","additionalProperties":false,"required":["session","revision","incarnation","title","lifecycle","activity","execution","queue_count","effective_limits","continuity","actions"],"properties":{"thread_ref":{"type":"string","minLength":1,"maxLength":160},"workspace":{"type":"string","minLength":1,"maxLength":32},"driver":{"type":"string","minLength":1,"maxLength":256},"provider":{"type":"string","minLength":1,"maxLength":128},"definition":{"type":"string","minLength":1,"maxLength":256},"last_result":{"$ref":"#/$defs/LastResult"},"session":{"$ref":"#/$defs/SessionRef"},"revision":{"$ref":"#/$defs/Pos"},"incarnation":{"$ref":"#/$defs/Pos"},"title":{"type":"string","maxLength":512},"lifecycle":{"enum":["opening","active","suspended","closing","closed"]},"activity":{"enum":["idle","working","blocked","stalled"]},"execution":{"type":"object","additionalProperties":false,"required":["state","evidence_at","stale"],"properties":{"state":{"enum":["absent","starting","running","quiescent","unknown"]},"evidence_at":{"$ref":"#/$defs/Time"},"stale":{"type":"boolean"}}},"queue_count":{"$ref":"#/$defs/Nat"},"effective_limits":{"$ref":"#/$defs/Limits"},"continuity":{"$ref":"#/$defs/Continuity"},"actions":{"$ref":"#/$defs/Actions"}}},
  "OpenReceipt":{"type":"object","additionalProperties":false,"required":["session","operation","snapshot"],"properties":{"session":{"$ref":"#/$defs/SessionRef"},"operation":{"$ref":"#/$defs/OpRef"},"snapshot":{"$ref":"#/$defs/SessionSnapshot"}}},
  "OperationState":{"type":"object","additionalProperties":false,"required":["operation","operation_key","revision","receipt","observation"],"properties":{"operation":{"$ref":"#/$defs/OpRef"},"operation_key":{"$ref":"#/$defs/Key"},"revision":{"$ref":"#/$defs/Pos"},"receipt":{"$ref":"#/$defs/OperationReceipt"},"observation":{"allOf":[{"$ref":"#/$defs/Await"},{"properties":{"subject_kind":{"const":"operation"}}}]}}},
  "GetValue":{"oneOf":[{"type":"object","additionalProperties":false,"required":["kind","value"],"properties":{"kind":{"const":"session"},"value":{"$ref":"#/$defs/SessionSnapshot"}}},{"type":"object","additionalProperties":false,"required":["kind","value"],"properties":{"kind":{"const":"work"},"value":{"$ref":"#/$defs/WorkState"}}},{"type":"object","additionalProperties":false,"required":["kind","value"],"properties":{"kind":{"const":"operation"},"value":{"$ref":"#/$defs/OperationState"}}}]},
  "Filter":{"type":"object","additionalProperties":false,"properties":{"activity":{"enum":["idle","working","blocked","stalled"]},"lifecycle":{"enum":["opening","active","suspended","closing","closed"]}}},
  "ListPage":{"type":"object","additionalProperties":false,"required":["items"],"properties":{"items":{"type":"array","maxItems":64,"items":{"$ref":"#/$defs/SessionSnapshot"}},"next":{"$ref":"#/$defs/Cursor"}}},
  "Candidate":{"type":"object","additionalProperties":false,"required":["ref","kind","title","status","checked_at","reasons","features","actions"],"properties":{"ref":{"$ref":"#/$defs/Ref"},"kind":{"enum":["definition","profile"]},"revision":{"$ref":"#/$defs/Pos"},"title":{"type":"string","maxLength":512},"status":{"enum":["ready","missing","unconfigured","incompatible","unknown"]},"checked_at":{"$ref":"#/$defs/Time"},"reasons":{"type":"array","maxItems":64,"items":{"$ref":"#/$defs/Text"}},"features":{"$ref":"#/$defs/Refs"},"actions":{"$ref":"#/$defs/Actions"}}},
  "CatalogPage":{"type":"object","additionalProperties":false,"required":["items","complete","unavailable_count","diagnostics"],"properties":{"items":{"type":"array","maxItems":64,"items":{"$ref":"#/$defs/Candidate"}},"next":{"$ref":"#/$defs/Cursor"},"complete":{"type":"boolean"},"unavailable_count":{"$ref":"#/$defs/Nat"},"diagnostics":{"type":"array","maxItems":64,"items":{"$ref":"#/$defs/Fault"}}}}
 },
 "tools":[
  {"name":"session_catalog","description":"Choose a ready admitted definition or profile using locate. Starts nothing and grants nothing. Set include_unavailable to show readiness reasons.","inputSchema":{"type":"object","additionalProperties":false,"properties":{"kind":{"enum":["definition","profile"],"default":"definition"},"include_unavailable":{"type":"boolean","default":false},"cursor":{"$ref":"#/$defs/Cursor"}}},"outputSchema":{"allOf":[{"$ref":"#/$defs/Reply"},{"properties":{"value":{"$ref":"#/$defs/CatalogPage"}}}]}},
  {"name":"session_open","description":"Open a reusable managed session without work. Keep its exact ref; submit work with session_send and retire it with session_close. Reuse this key after a lost reply; changing input under the key is a conflict.","inputSchema":{"type":"object","additionalProperties":false,"required":["spec","operation_key"],"properties":{"spec":{"$ref":"#/$defs/ManagedSpec"},"operation_key":{"$ref":"#/$defs/Key"}}},"outputSchema":{"allOf":[{"$ref":"#/$defs/MutationReply"},{"properties":{"value":{"$ref":"#/$defs/OpenReceipt"}}}]}},
  {"name":"session_run","description":"Open a managed session and submit its first unit of durable work. Returns a WorkRef receipt, not the answer; await that work. Reuse this key after a lost reply; changing input under the key is a conflict.","inputSchema":{"type":"object","additionalProperties":false,"required":["spec","input","operation_key"],"properties":{"spec":{"$ref":"#/$defs/ManagedSpec"},"input":{"$ref":"#/$defs/Input"},"output":{"$ref":"#/$defs/Ref"},"operation_key":{"$ref":"#/$defs/Key"}}},"outputSchema":{"allOf":[{"$ref":"#/$defs/MutationReply"},{"properties":{"value":{"$ref":"#/$defs/WorkReceipt"}}}]}},
  {"name":"session_send","description":"Submit work: a task, follow-up or correction. Durably queues while busy and wakes eligible managed work; a thread note does not. Await the WorkRef receipt. Reuse this key after a lost reply; changing input under the key is a conflict.","inputSchema":{"type":"object","additionalProperties":false,"required":["session","input","operation_key"],"properties":{"session":{"$ref":"#/$defs/SessionRef"},"input":{"$ref":"#/$defs/Input"},"output":{"$ref":"#/$defs/Ref"},"operation_key":{"$ref":"#/$defs/Key"}}},"outputSchema":{"allOf":[{"$ref":"#/$defs/MutationReply"},{"properties":{"value":{"$ref":"#/$defs/WorkReceipt"}}}]}},
  {"name":"session_await","description":"Observe one exact work or operation. Returns a tagged ready, pending, blocked or uncertain observation. Queued/accepted is not done; timeout never cancels.","inputSchema":{"type":"object","additionalProperties":false,"required":["subject"],"properties":{"subject":{"$ref":"#/$defs/Subject"},"timeout_ms":{"$ref":"#/$defs/Timeout"}}},"outputSchema":{"allOf":[{"$ref":"#/$defs/Reply"},{"properties":{"value":{"$ref":"#/$defs/Await"}}}]}},
  {"name":"session_join","description":"Join an exact ordered work set; returns every child's observation. Defaults to all_success; uncertain work remains unresolved. Reuse this key after a lost reply; changing input under the key is a conflict.","inputSchema":{"type":"object","additionalProperties":false,"required":["works","operation_key"],"properties":{"works":{"$ref":"#/$defs/Works"},"policy":{"enum":["all_success","all_settled","first_success","quorum"],"default":"all_success"},"quorum":{"type":"integer","minimum":1,"maximum":64},"timeout_ms":{"$ref":"#/$defs/Timeout"},"operation_key":{"$ref":"#/$defs/Key"}},"if":{"required":["policy"],"properties":{"policy":{"const":"quorum"}}},"then":{"required":["quorum"]},"else":{"not":{"required":["quorum"]}}},"outputSchema":{"allOf":[{"$ref":"#/$defs/MutationReply"},{"properties":{"value":{"$ref":"#/$defs/JoinAwait"}}}]}},
  {"name":"session_get","description":"Inspect an exact session, work or operation; or recover an operation by your saved operation_key in your caller/workspace namespace. Never infer work completion from an attempt or newest run.","inputSchema":{"type":"object","additionalProperties":false,"properties":{"session":{"$ref":"#/$defs/SessionRef"},"work":{"$ref":"#/$defs/WorkRef"},"operation":{"$ref":"#/$defs/OpRef"}},"oneOf":[{"required":["session"]},{"required":["work"]},{"required":["operation"]}]},"outputSchema":{"allOf":[{"$ref":"#/$defs/Reply"},{"properties":{"value":{"$ref":"#/$defs/GetValue"}}}]}},
  {"name":"session_list","description":"List durable sessions, including idle and closed sessions. Filter by lifecycle or activity; new-launch availability never filters existing sessions.","inputSchema":{"type":"object","additionalProperties":false,"properties":{"filter":{"$ref":"#/$defs/Filter"},"cursor":{"$ref":"#/$defs/Cursor"}}},"outputSchema":{"allOf":[{"$ref":"#/$defs/Reply"},{"properties":{"value":{"$ref":"#/$defs/ListPage"}}}]}},
  {"name":"session_cancel","description":"Request cancellation of one work and its owned descendants, keeping its session open. Receipt says requested; await its operation for stopped/already_terminal or uncertain evidence. Reuse this key after a lost reply; changing input under the key is a conflict.","inputSchema":{"type":"object","additionalProperties":false,"required":["work","operation_key"],"properties":{"work":{"$ref":"#/$defs/WorkRef"},"reason":{"$ref":"#/$defs/Text"},"expected_incarnation":{"type":"integer","minimum":1,"default":1},"operation_key":{"$ref":"#/$defs/Key"}}},"outputSchema":{"allOf":[{"$ref":"#/$defs/MutationReply"},{"properties":{"value":{"$ref":"#/$defs/ControlReceipt"}}},{"properties":{"value":{"properties":{"effect":{"const":"cancel"},"subject":{"$ref":"#/$defs/WorkRef"}}}}}]}},
  {"name":"session_close","description":"Seal session intake and drain. Await the operation for closure; closing a view is separate. Reuse this key after a lost reply; changing input under the key is a conflict.","inputSchema":{"type":"object","additionalProperties":false,"required":["session","operation_key"],"properties":{"session":{"$ref":"#/$defs/SessionRef"},"expected_incarnation":{"type":"integer","minimum":1,"default":1},"operation_key":{"$ref":"#/$defs/Key"}}},"outputSchema":{"allOf":[{"$ref":"#/$defs/MutationReply"},{"properties":{"value":{"$ref":"#/$defs/ControlReceipt"}}},{"properties":{"value":{"properties":{"effect":{"const":"close"},"subject":{"$ref":"#/$defs/SessionRef"}}}}}]}}
 ]
}
]==]
